    <Page
      title="Feature Requests"
      subtitle="Vote on features or suggest new ones. We review every request and ship based on community votes."
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={{
        content: "Suggest a Feature",
        icon: PlusIcon,
        onAction: () => setModalOpen(true),
      }}
      titleMetadata={
        isAdmin ? <Badge tone="info">Admin</Badge> : undefined
      }
    >
      <Box paddingBlockEnd="1600">
        <Layout>

          {/* ---- Stats Bar ---- */}
          <Layout.Section>
            <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
              <Box
                padding="400"
                background="bg-surface"
                borderWidth="025"
                borderColor="border"
                borderRadius="200"
              >
                <BlockStack gap="100">
                  <Text as="p" tone="subdued" variant="bodySm">
                    Total Requests
                  </Text>
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.total}
                  </Text>
                </BlockStack>
              </Box>
              <Box
                padding="400"
                background="bg-surface-warning"
                borderWidth="025"
                borderColor="border-warning"
                borderRadius="200"
              >
                <BlockStack gap="100">
                  <Text as="p" tone="caution" variant="bodySm">
                    Under Review
                  </Text>
                  <Text
                    as="p"
                    variant="headingXl"
                    fontWeight="bold"
                    tone="caution"
                  >
                    {stats.under_review}
                  </Text>
                </BlockStack>
              </Box>
              <Box
                padding="400"
                background="bg-surface-info"
                borderWidth="025"
                borderColor="border-info"
                borderRadius="200"
              >
                <BlockStack gap="100">
                  <Text as="p" tone="subdued" variant="bodySm">
                    Planned
                  </Text>
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.planned}
                  </Text>
                </BlockStack>
              </Box>
              <Box
                padding="400"
                background="bg-surface-magic"
                borderWidth="025"
                borderColor="border-magic"
                borderRadius="200"
              >
                <BlockStack gap="100">
                  <Text as="p" tone="subdued" variant="bodySm">
                    In Progress
                  </Text>
                  <Text as="p" variant="headingXl" fontWeight="bold">
                    {stats.in_progress}
                  </Text>
                </BlockStack>
              </Box>
              <Box
                padding="400"
                background="bg-surface-success"
                borderWidth="025"
                borderColor="border-success"
                borderRadius="200"
              >
                <BlockStack gap="100">
                  <Text as="p" tone="success" variant="bodySm">
                    Done / Shipped
                  </Text>
                  <Text
                    as="p"
                    variant="headingXl"
                    fontWeight="bold"
                    tone="success"
                  >
                    {stats.done}
                  </Text>
