170→
171→export const loader = async ({ request }: LoaderFunctionArgs) => {
172→  const { session } = await authenticate.admin(request);
173→  const shop = session.shop;
174→
175→  const [features, myVotes] = await Promise.all([
176→    db.featureRequest.findMany({
177→      orderBy: { votesCount: "desc" },
178→      take: 500,
179→    }),
180→    db.featureVote.findMany({
181→      where: { shop },
182→      select: { featureRequestId: true },
183→    }),
184→  ]);
185→
186→  const votedIds = myVotes.map((v) => v.featureRequestId);
187→
188→  const stats = {
189→    total: features.length,
190→    under_review: features.filter((f) => f.status === "under_review").length,
191→    planned: features.filter((f) => f.status === "planned").length,
192→    in_progress: features.filter((f) => f.status === "in_progress").length,
193→    done: features.filter(
194→      (f) => f.status === "done" || f.status === "shipped",
195→    ).length,
196→  };
197→
198→  const isAdmin = shop === ADMIN_SHOP;
199→
200→  return { features, votedIds, shop, stats, isAdmin };
201→};
