155→export const action = async ({ request }: ActionFunctionArgs): Promise<
156→  | { error: string }
157→  | { success: boolean; message: string }
158→  | null
159→> => {
160→  const { session, billing } = await authenticate.admin(request);
161→  const shop = session.shop;
162→  const formData = await request.formData();
163→  const intent = String(formData.get("intent"));
164→
165→  if (intent === "subscribe") {
166→    const plan = String(formData.get("plan"));
167→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
168→    try {
169→      /* eslint-disable @typescript-eslint/no-explicit-any */
170→      // billing.request() throws a redirect Response to Shopify's
171→      // billing confirmation page — we must let it propagate.
172→      await billing.request({
173→        plan: plan as any,
174→        isTest: process.env.NODE_ENV !== "production",
175→        returnUrl,
176→      });
177→      /* eslint-enable @typescript-eslint/no-explicit-any */
178→      return null;
179→    } catch (error) {
180→      // Re-throw Response redirects so React Router / App Bridge handles them
181→      if (error instanceof Response) throw error;
182→      // BillingError has errorData with Shopify userErrors
183→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
184→      const details = errorData?.map((e) => e.message).join(", ");
185→      const message = details || (error instanceof Error ? error.message : String(error));
186→
187→      // Provide a helpful message for common billing errors
188→      if (message.includes("Custom apps cannot use the Billing API")) {
189→        return {
190→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
191→        };
192→      }
193→      return {
194→        error: `Failed to initiate subscription: ${message}`,
195→      };
196→    }
197→  }
198→
199→  // Set plan directly in database (for custom apps where Billing API is unavailable)
200→  if (intent === "test-set-plan") {
201→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
202→    const validTiers = ["free", "starter", "pro", "ultimate"];
203→    if (!validTiers.includes(tier)) {
204→      return { error: `Invalid plan tier: ${tier}` };
205→    }
206→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
207→    await db.subscription.upsert({
208→      where: { shop },
209→      create: { shop, planId, billingInterval: "monthly", status: "active" },
210→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
211→    });
212→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
213→  }
214→
215→  if (intent === "cancel") {
216→    try {
217→      const sub = await getShopSubscription(shop);
218→      if (sub.shopifySubscriptionId) {
219→        await billing.cancel({
220→          subscriptionId: sub.shopifySubscriptionId,
221→          isTest: process.env.NODE_ENV !== "production",
222→          prorate: true,
223→        });
224→      }
225→      await cancelShopSubscription(shop);
226→      return {
227→        success: true,
228→        message: "Subscription cancelled. You are now on the Free plan.",
229→      };
230→    } catch {
231→      return { error: "Failed to cancel subscription. Please try again." };
232→    }
233→  }
234→
235→  return null;
236→};
237→
238→// ─── Feature row ─────────────────────────────────────────────────────────────
239→
240→function PlanFeature({ feature }: { feature: string }) {
241→  return (
242→    <InlineStack gap="200" blockAlign="start" wrap={false}>
243→      <Box>
244→        <Icon source={CheckCircleIcon} tone="success" />
245→      </Box>
246→      <Text as="span" variant="bodyMd">
247→        {feature}
248→      </Text>
249→    </InlineStack>
250→  );
251→}
252→
253→// ─── Plan card ────────────────────────────────────────────────────────────────
254→
255→type PlanCardProps = {
256→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
257→  isAnnual: boolean;
258→  currentTier: string;
259→  onSubscribe: (planName: string) => void;
260→  onRequestCancel: () => void;
261→  loadingPlan: string | null;
262→};
263→
264→function PlanCard({
265→  plan,
266→  isAnnual,
267→  currentTier,
268→  onSubscribe,
269→  onRequestCancel,
270→  loadingPlan,
271→}: PlanCardProps) {
272→  const isCurrent = currentTier === plan.id;
273→  const isBestValue = "bestValue" in plan && plan.bestValue;
274→  const isCurrentPaid = currentTier !== "free";
275→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
276→
277→  const TIER_ORDER: Record<string, number> = {
278→    free: 0,
279→    starter: 1,
280→    pro: 2,
281→    ultimate: 3,
282→  };
283→  const isUpgrade =
284→    !isCurrent &&
285→    plan.id !== "free" &&
286→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
287→
288→  const shopifyPlan = isAnnual
289→    ? plan.shopifyPlanAnnual
290→    : plan.shopifyPlanMonthly;
291→
292→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
293→
294→  let buttonContent = "Start 7-day free trial";
295→  if (isCurrent) {
296→    buttonContent = "Current plan";
297→  } else if (isDowngradeToFree) {
298→    buttonContent = "Downgrade to Free";
299→  } else if (isUpgrade) {
300→    buttonContent = `Upgrade to ${plan.name}`;
301→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
302→    buttonContent = `Switch to ${plan.name}`;
303→  }
304→
305→  const handleClick = () => {
306→    if (isCurrent) return;
307→    if (isDowngradeToFree) {
308→      onRequestCancel();
309→    } else if (shopifyPlan) {
310→      onSubscribe(shopifyPlan);
311→    }
312→  };
313→
314→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
315→
316→  return (
317→    <Box
318→      background="bg-surface"
319→      borderWidth="025"
320→      borderColor={isBestValue ? "border-info" : "border"}
321→      borderRadius="300"
322→      padding="0"
323→      overflowX="hidden"
324→      overflowY="hidden"
325→    >
326→      {/* Best value ribbon */}
327→      {isBestValue && (
328→        <Box background="bg-fill-info" padding="200">
329→          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
330→            Most Popular
331→          </Text>
332→        </Box>
333→      )}
334→
335→      <Box padding="400">
336→        <BlockStack gap="400">
337→          {/* Plan name + badge */}
338→          <InlineStack align="space-between" blockAlign="center">
339→            <Text as="h3" variant="headingMd" fontWeight="bold">
340→              {plan.name}
341→            </Text>
342→            {isCurrent && <Badge tone="success">Active</Badge>}
343→          </InlineStack>
344→
345→          {/* Price */}
346→          <BlockStack gap="050">
347→            <InlineStack gap="100" blockAlign="baseline">
348→              <Text as="p" variant="headingXl" fontWeight="bold">
349→                ${displayPrice}
350→              </Text>
351→              <Text as="p" variant="bodySm" tone="subdued">
352→                / month
353→              </Text>
354→            </InlineStack>
355→            <Text as="p" variant="bodySm" tone="subdued">
356→              {isAnnual
357→                ? `billed $${plan.annualPrice} / year`
358→                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
359→            </Text>
360→          </BlockStack>
361→
362→          {/* CTA Button */}
363→          <Button
364→            variant={isCurrent ? "secondary" : "primary"}
365→            tone={isDowngradeToFree ? "critical" : undefined}
366→            onClick={handleClick}
367→            disabled={isCurrent}
368→            loading={isThisLoading}
369→            fullWidth
370→          >
371→            {buttonContent}
372→          </Button>
373→
374→          <Divider />
375→
376→          {/* Features list */}
377→          <BlockStack gap="200">
378→            <Text as="p" variant="bodySm" fontWeight="semibold" tone="subdued">
379→              {plan.id === "ultimate" ? "Everything in Pro, plus:" : "Includes:"}
380→            </Text>
381→            {plan.features.map((f) => (
382→              <PlanFeature key={f} feature={f} />
383→            ))}
384→          </BlockStack>
385→        </BlockStack>
386→      </Box>
387→    </Box>
388→  );
389→}
390→
391→// ─── Page ─────────────────────────────────────────────────────────────────────
392→
393→export default function PricingPage() {
394→  const { subscription, isDev } = useLoaderData<typeof loader>();
395→  const fetcher = useFetcher<typeof action>();
396→  const navigate = useNavigate();
397→  const shopify = useAppBridge();
398→
399→  const [isAnnual, setIsAnnual] = useState(
400→    subscription.billingInterval === "annual",
