453→          </Layout.Section>
454→        )}
455→        <Layout.Section>
456→          <BlockStack gap="600">
457→
458→            {/* Billing toggle */}
459→            <BlockStack gap="200" inlineAlign="center">
460→              <ButtonGroup variant="segmented">
461→                <Button
462→                  pressed={!isAnnual}
463→                  onClick={() => setIsAnnual(false)}
464→                >
465→                  Monthly
466→                </Button>
467→                <Button
468→                  pressed={isAnnual}
469→                  onClick={() => setIsAnnual(true)}
470→                >
471→                  Annual · Save up to 38%
472→                </Button>
473→              </ButtonGroup>
474→              {isAnnual && (
475→                <Badge tone="success">You save up to 38% per year</Badge>
476→              )}
477→            </BlockStack>
478→
479→            {/* Free plan — compact card */}
480→            <Box
481→              background="bg-surface"
482→              borderWidth="025"
483→              borderColor="border"
484→              borderRadius="300"
485→              padding="400"
486→            >
487→              <InlineStack align="space-between" blockAlign="center" wrap>
488→                <InlineStack gap="300" blockAlign="center">
489→                  <BlockStack gap="050">
