498→                    </Text>
499→                  </BlockStack>
500→                </InlineStack>
501→                <InlineStack gap="200" blockAlign="center">
502→                  <Text as="p" variant="headingSm" fontWeight="bold">
503→                    $0
504→                  </Text>
505→                  <Text as="p" variant="bodySm" tone="subdued">
506→                    forever
507→                  </Text>
508→                </InlineStack>
509→              </InlineStack>
