 41→
 42→// ─── Plan data ────────────────────────────────────────────────────────────────
 43→
 44→const PLANS_DATA = {
 45→  free: {
 46→    id: "free",
 47→    name: "Free",
 48→    monthlyPrice: 0,
 49→    annualPrice: 0,
 50→    annualMonthlyPrice: 0,
 51→    description: "Get started and try it out",
