 60→    shopifyPlanAnnual: null as string | null,
 61→  },
 62→  starter: {
 63→    id: "starter",
 64→    name: "Starter",
 65→    monthlyPrice: 4.99,
 66→    annualPrice: 39,
 67→    annualMonthlyPrice: 3.25,
 68→    description: "Essential features for small stores",
 69→    features: [
 70→      "Up to 500 zip codes",
 71→      "Delivery ETA & COD info",
 72→      "Full widget customization",
