 80→    shopifyPlanAnnual: PLAN_STARTER_ANNUAL,
 81→  },
 82→  pro: {
 83→    id: "pro",
 84→    name: "Pro",
 85→    monthlyPrice: 9.99,
 86→    annualPrice: 79,
 87→    annualMonthlyPrice: 6.58,
 88→    description: "For growing stores that need full control",
 89→    features: [
 90→      "Unlimited zip codes",
 91→      "Allowed + Blocked zip codes",
 92→      "Unlimited delivery rules",
 93→      "Full customer waitlist",
 94→      "Bulk CSV import & export",
 95→      "Cart & checkout blocking",
 96→      "Priority email support",
 97→    ],
 98→    shopifyPlanMonthly: PLAN_PRO_MONTHLY,
 99→    shopifyPlanAnnual: PLAN_PRO_ANNUAL,
100→    bestValue: true,
101→  },
102→  ultimate: {
103→    id: "ultimate",
104→    name: "Ultimate",
105→    monthlyPrice: 19.99,
106→    annualPrice: 149,
107→    annualMonthlyPrice: 12.42,
108→    description: "Enterprise-grade power and flexibility",
109→    features: [
110→      "Everything in Pro, plus:",
111→      "Custom widget CSS",
112→      "API access",
113→      "24/7 VIP support",
114→      "Early access to new features",
115→    ],
116→    shopifyPlanMonthly: PLAN_ULTIMATE_MONTHLY,
117→    shopifyPlanAnnual: PLAN_ULTIMATE_ANNUAL,
118→  },
119→};
120→
121→// ─── Feature comparison rows ─────────────────────────────────────────────────
122→
123→type FeatureValue = boolean | string;
124→
125→const FEATURE_ROWS: { label: string; free: FeatureValue; starter: FeatureValue; pro: FeatureValue; ultimate: FeatureValue }[] = [
126→  { label: "Zip codes", free: "20", starter: "500", pro: "Unlimited", ultimate: "Unlimited" },
127→  { label: "Blocked zip codes", free: false, starter: false, pro: true, ultimate: true },
128→  { label: "Delivery rules", free: false, starter: "3", pro: "Unlimited", ultimate: "Unlimited" },
129→  { label: "Waitlist entries", free: false, starter: "25", pro: "Unlimited", ultimate: "Unlimited" },
130→  { label: "Widget customization", free: false, starter: true, pro: true, ultimate: true },
131→  { label: "Delivery ETA & COD", free: false, starter: true, pro: true, ultimate: true },
132→  { label: "Zone organization", free: false, starter: true, pro: true, ultimate: true },
133→  { label: "CSV import", free: false, starter: true, pro: true, ultimate: true },
134→  { label: "CSV export", free: false, starter: false, pro: true, ultimate: true },
135→  { label: "Cart & checkout blocking", free: false, starter: false, pro: true, ultimate: true },
136→  { label: "Custom widget CSS", free: false, starter: false, pro: false, ultimate: true },
137→  { label: "API access", free: false, starter: false, pro: false, ultimate: true },
138→  { label: "Priority support", free: false, starter: false, pro: true, ultimate: "24/7 VIP" },
139→];
140→
141→const PLAN_ORDER = ["free", "starter", "pro", "ultimate"] as const;
142→
143→const TIER_ORDER: Record<string, number> = {
144→  free: 0,
145→  starter: 1,
146→  pro: 2,
147→  ultimate: 3,
148→};
149→
150→// ─── Loader ───────────────────────────────────────────────────────────────────
151→
152→export const loader = async ({ request }: LoaderFunctionArgs) => {
153→  const { session } = await authenticate.admin(request);
154→  const shop = session.shop;
155→  const subscription = await getShopSubscription(shop);
156→  const isDev = process.env.NODE_ENV !== "production";
157→  return { subscription, isDev };
158→};
159→
160→// ─── Action ───────────────────────────────────────────────────────────────────
161→
162→export const action = async ({ request }: ActionFunctionArgs): Promise<
163→  | { error: string }
164→  | { success: boolean; message: string }
165→  | null
166→> => {
167→  const { session, billing } = await authenticate.admin(request);
168→  const shop = session.shop;
169→  const formData = await request.formData();
170→  const intent = String(formData.get("intent"));
171→
172→  if (intent === "subscribe") {
173→    const plan = String(formData.get("plan"));
174→    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
175→    try {
176→      /* eslint-disable @typescript-eslint/no-explicit-any */
177→      await billing.request({
178→        plan: plan as any,
179→        isTest: process.env.NODE_ENV !== "production",
180→        returnUrl,
181→      });
182→      /* eslint-enable @typescript-eslint/no-explicit-any */
183→      return null;
184→    } catch (error) {
185→      if (error instanceof Response) throw error;
186→      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
187→      const details = errorData?.map((e) => e.message).join(", ");
188→      const message = details || (error instanceof Error ? error.message : String(error));
189→
190→      if (message.includes("Custom apps cannot use the Billing API")) {
191→        return {
192→          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
193→        };
194→      }
195→      return {
196→        error: `Failed to initiate subscription: ${message}`,
197→      };
198→    }
199→  }
200→
201→  if (intent === "test-set-plan") {
202→    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
203→    const validTiers = ["free", "starter", "pro", "ultimate"];
204→    if (!validTiers.includes(tier)) {
205→      return { error: `Invalid plan tier: ${tier}` };
206→    }
207→    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
208→    await db.subscription.upsert({
209→      where: { shop },
210→      create: { shop, planId, billingInterval: "monthly", status: "active" },
211→      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
212→    });
213→    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
214→  }
215→
216→  if (intent === "cancel") {
217→    try {
218→      const sub = await getShopSubscription(shop);
219→      if (sub.shopifySubscriptionId) {
220→        await billing.cancel({
221→          subscriptionId: sub.shopifySubscriptionId,
222→          isTest: process.env.NODE_ENV !== "production",
223→          prorate: true,
224→        });
225→      }
226→      await cancelShopSubscription(shop);
227→      return {
228→        success: true,
229→        message: "Subscription cancelled. You are now on the Free plan.",
230→      };
231→    } catch {
232→      return { error: "Failed to cancel subscription. Please try again." };
233→    }
234→  }
235→
236→  return null;
237→};
238→
239→// ─── Feature row component ───────────────────────────────────────────────────
240→
241→function PlanFeature({ feature }: { feature: string }) {
242→  return (
243→    <InlineStack gap="200" blockAlign="start" wrap={false}>
244→      <Box>
245→        <Icon source={CheckCircleIcon} tone="success" />
246→      </Box>
247→      <Text as="span" variant="bodyMd">
248→        {feature}
249→      </Text>
250→    </InlineStack>
251→  );
252→}
253→
254→// ─── Plan card ────────────────────────────────────────────────────────────────
255→
256→type PlanCardProps = {
257→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
258→  isAnnual: boolean;
259→  currentTier: string;
260→  onSubscribe: (planName: string) => void;
261→  onRequestCancel: () => void;
262→  loadingPlan: string | null;
263→};
264→
265→function PlanCard({
266→  plan,
267→  isAnnual,
268→  currentTier,
269→  onSubscribe,
270→  onRequestCancel,
271→  loadingPlan,
272→}: PlanCardProps) {
273→  const isCurrent = currentTier === plan.id;
274→  const isBestValue = "bestValue" in plan && plan.bestValue;
275→  const isCurrentPaid = currentTier !== "free";
276→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
277→
278→  const isUpgrade =
279→    !isCurrent &&
280→    plan.id !== "free" &&
281→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
282→
283→  const shopifyPlan = isAnnual
284→    ? plan.shopifyPlanAnnual
285→    : plan.shopifyPlanMonthly;
286→
287→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
288→
289→  let buttonContent = "Start 7-day free trial";
290→  if (isCurrent) {
291→    buttonContent = "Current plan";
292→  } else if (isDowngradeToFree) {
293→    buttonContent = "Downgrade to Free";
294→  } else if (isUpgrade) {
295→    buttonContent = `Upgrade to ${plan.name}`;
296→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
297→    buttonContent = `Switch to ${plan.name}`;
298→  }
299→
300→  const handleClick = () => {
301→    if (isCurrent) return;
302→    if (isDowngradeToFree) {
303→      onRequestCancel();
304→    } else if (shopifyPlan) {
305→      onSubscribe(shopifyPlan);
306→    }
307→  };
308→
309→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
310→
311→  return (
312→    <Box
313→      background="bg-surface"
314→      borderWidth="025"
315→      borderColor={isCurrent ? "border-success" : isBestValue ? "border-info" : "border"}
316→      borderRadius="300"
317→      padding="0"
318→      overflowX="hidden"
319→      overflowY="hidden"
320→    >
321→      {/* Best value / Current ribbon */}
322→      {isBestValue && !isCurrent && (
323→        <Box background="bg-fill-info" paddingBlock="150" paddingInline="400">
324→          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
325→            Most Popular
326→          </Text>
327→        </Box>
328→      )}
329→      {isCurrent && (
330→        <Box background="bg-fill-success" paddingBlock="150" paddingInline="400">
331→          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
332→            Current Plan
333→          </Text>
334→        </Box>
335→      )}
336→      {!isBestValue && !isCurrent && (
337→        <Box paddingBlock="150" paddingInline="400">
338→          <Text as="p" variant="bodySm" alignment="center">
339→            &nbsp;
340→          </Text>
341→        </Box>
342→      )}
343→
344→      <Box padding="500">
345→        <BlockStack gap="400">
346→          {/* Plan name + description */}
347→          <BlockStack gap="100">
348→            <Text as="h3" variant="headingLg" fontWeight="bold">
349→              {plan.name}
350→            </Text>
351→            <Text as="p" variant="bodySm" tone="subdued">
352→              {plan.description}
353→            </Text>
354→          </BlockStack>
355→
356→          {/* Price */}
357→          <BlockStack gap="100">
358→            <InlineStack gap="100" blockAlign="baseline" wrap={false}>
359→              <Text as="p" variant="heading2xl" fontWeight="bold">
360→                ${displayPrice}
361→              </Text>
362→              <Text as="p" variant="bodyMd" tone="subdued">
363→                /month
364→              </Text>
365→            </InlineStack>
366→            {plan.monthlyPrice > 0 && (
367→              <Text as="p" variant="bodySm" tone="subdued">
368→                {isAnnual
369→                  ? `$${plan.annualPrice} billed annually`
370→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
371→              </Text>
372→            )}
373→            {plan.monthlyPrice === 0 && (
374→              <Text as="p" variant="bodySm" tone="subdued">
375→                Free forever
376→              </Text>
377→            )}
378→          </BlockStack>
379→
380→          {/* CTA Button */}
381→          <Button
382→            variant={isCurrent ? "tertiary" : isUpgrade ? "primary" : "secondary"}
383→            tone={isDowngradeToFree ? "critical" : undefined}
384→            onClick={handleClick}
385→            disabled={isCurrent}
386→            loading={isThisLoading}
387→            fullWidth
388→            size="large"
389→          >
390→            {buttonContent}
391→          </Button>
392→
393→          <Divider />
394→
395→          {/* Features list */}
396→          <BlockStack gap="200">
397→            <Text as="p" variant="bodySm" fontWeight="semibold">
398→              Includes:
399→            </Text>
400→            {plan.features.map((f) => (
401→              <PlanFeature key={f} feature={f} />
402→            ))}
403→          </BlockStack>
404→        </BlockStack>
405→      </Box>
406→    </Box>
407→  );
408→}
409→
410→// ─── Comparison cell ──────────────────────────────────────────────────────────
411→
412→function ComparisonCell({ value, isCurrentPlan }: { value: FeatureValue; isCurrentPlan: boolean }) {
413→  return (
414→    <Box>
415→      <InlineStack align="center" blockAlign="center">
416→        {typeof value === "string" ? (
417→          <Text
418→            as="p"
419→            variant="bodyMd"
420→            fontWeight={isCurrentPlan ? "semibold" : "regular"}
421→            alignment="center"
422→          >
423→            {value}
424→          </Text>
425→        ) : (
426→          <Icon
427→            source={value ? CheckCircleIcon : XCircleIcon}
428→            tone={value ? "success" : "subdued"}
429→          />
430→        )}
431→      </InlineStack>
432→    </Box>
433→  );
434→}
435→
436→// ─── Page ─────────────────────────────────────────────────────────────────────
437→
438→export default function PricingPage() {
439→  const { subscription, isDev } = useLoaderData<typeof loader>();
440→  const fetcher = useFetcher<typeof action>();
441→  const navigate = useNavigate();
442→  const shopify = useAppBridge();
443→
444→  const [isAnnual, setIsAnnual] = useState(
445→    subscription.billingInterval === "annual",
446→  );
447→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
448→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
449→
450→  const data = fetcher.data;
451→  const isFetching = fetcher.state !== "idle";
452→
453→  useEffect(() => {
454→    if (!isFetching) setLoadingPlan(null);
455→    if (data && "message" in data && data.message) {
456→      shopify.toast.show(data.message as string);
457→    }
458→  }, [data, isFetching, shopify]);
459→
460→  const actionError =
461→    data && "error" in data && data.error ? (data.error as string) : null;
462→
463→  const handleSubscribe = useCallback(
464→    (planName: string) => {
465→      setLoadingPlan(planName);
466→      const fd = new FormData();
467→      fd.set("intent", "subscribe");
468→      fd.set("plan", planName);
469→      fetcher.submit(fd, { method: "POST" });
470→    },
471→    [fetcher],
472→  );
473→
474→  const handleConfirmCancel = useCallback(() => {
475→    setCancelModalOpen(false);
476→    setLoadingPlan("cancel");
477→    const fd = new FormData();
478→    fd.set("intent", "cancel");
479→    fetcher.submit(fd, { method: "POST" });
480→  }, [fetcher]);
481→
482→  const currentTier = subscription.planTier;
483→
484→  return (
485→    <Page
486→      title="Pricing"
487→      subtitle="Choose the plan that's right for your store"
488→      backAction={{ onAction: () => navigate("/app") }}
489→    >
490→      <Box paddingBlockEnd="1600">
491→        <BlockStack gap="800">
492→
493→          {/* Error banner */}
494→          {actionError && (
495→            <Banner tone="critical" title="Billing error">
496→              <Text as="p" variant="bodyMd">{actionError}</Text>
497→            </Banner>
498→          )}
499→
500→          {/* Billing toggle */}
501→          <InlineStack align="center">
502→            <ButtonGroup variant="segmented">
503→              <Button
504→                pressed={!isAnnual}
505→                onClick={() => setIsAnnual(false)}
506→              >
507→                Monthly
508→              </Button>
509→              <Button
510→                pressed={isAnnual}
511→                onClick={() => setIsAnnual(true)}
512→              >
513→                Annual · Save up to 38%
514→              </Button>
515→            </ButtonGroup>
516→          </InlineStack>
517→
518→          {/* Free plan — full-width card */}
519→          <Box
520→            background="bg-surface"
521→            borderWidth="025"
