278→type PlanCardProps = {
279→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
280→  isAnnual: boolean;
281→  currentTier: string;
282→  onSubscribe: (planName: string) => void;
283→  loadingPlan: string | null;
284→};
285→
286→function PlanCard({
287→  plan,
288→  isAnnual,
289→  currentTier,
290→  onSubscribe,
291→  loadingPlan,
292→}: PlanCardProps) {
293→  const isCurrent = currentTier === plan.id;
294→  const isBestValue = "bestValue" in plan && plan.bestValue;
295→  const isCurrentPaid = currentTier !== "free";
296→
297→  const isUpgrade =
298→    !isCurrent &&
299→    plan.id !== "free" &&
300→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
301→
302→  const isDowngrade =
303→    !isCurrent &&
304→    plan.id !== "free" &&
305→    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);
306→
307→  const shopifyPlan = isAnnual
308→    ? plan.shopifyPlanAnnual
309→    : plan.shopifyPlanMonthly;
310→
311→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
312→
313→  let buttonContent = "Start free trial";
314→  let buttonVariant: "primary" | "secondary" | "tertiary" = "primary";
315→  let buttonTone: "critical" | undefined;
316→
317→  if (isCurrent) {
318→    buttonContent = "Current plan";
319→    buttonVariant = "tertiary";
320→  } else if (isUpgrade) {
321→    buttonContent = `Upgrade to ${plan.name}`;
322→    buttonVariant = "primary";
323→  } else if (isDowngrade && isCurrentPaid) {
324→    buttonContent = `Switch to ${plan.name}`;
325→    buttonVariant = "secondary";
326→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
327→    buttonContent = `Switch to ${plan.name}`;
328→    buttonVariant = "secondary";
329→  }
330→
331→  const handleClick = () => {
332→    if (isCurrent) return;
333→    if (shopifyPlan) {
334→      onSubscribe(shopifyPlan);
335→    }
336→  };
337→
338→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
339→
340→  // Determine ribbon
341→  const showRibbon = isBestValue || isCurrent;
342→  const ribbonBg = isCurrent ? "bg-fill-success" : "bg-fill-info";
343→  const ribbonText = isCurrent ? "Your Plan" : "Most Popular";
344→
345→  return (
346→    <Box
347→      background="bg-surface"
348→      borderWidth="025"
349→      borderColor={isCurrent ? "border-success" : isBestValue ? "border-info" : "border"}
350→      borderRadius="300"
351→      padding="0"
352→      overflowX="hidden"
353→      overflowY="hidden"
354→    >
355→      {/* Ribbon — only for current plan or best value */}
356→      {showRibbon && (
357→        <Box background={ribbonBg} paddingBlock="100" paddingInline="400">
358→          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
359→            {ribbonText}
360→          </Text>
361→        </Box>
362→      )}
363→
364→      <Box padding="500" paddingBlockStart={showRibbon ? "400" : "500"}>
365→        <BlockStack gap="500">
366→
367→          {/* Header: name + description */}
368→          <BlockStack gap="100">
369→            <Text as="h3" variant="headingLg" fontWeight="bold">
370→              {plan.name}
371→            </Text>
372→            <Text as="p" variant="bodySm" tone="subdued">
373→              {plan.description}
374→            </Text>
375→          </BlockStack>
376→
377→          {/* Price block */}
378→          <BlockStack gap="050">
379→            <InlineStack gap="050" blockAlign="baseline" wrap={false}>
380→              <Text as="p" variant="heading2xl" fontWeight="bold">
381→                ${displayPrice}
382→              </Text>
383→              <Text as="p" variant="bodySm" tone="subdued">
384→                /mo
385→              </Text>
386→            </InlineStack>
387→            <Text as="p" variant="bodySm" tone="subdued">
388→              {isAnnual
389→                ? `$${plan.annualPrice} billed annually`
390→                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
391→            </Text>
392→          </BlockStack>
393→
394→          {/* CTA */}
395→          <Button
396→            variant={buttonVariant}
397→            tone={buttonTone}
398→            onClick={handleClick}
399→            disabled={isCurrent}
400→            loading={isThisLoading}
401→            fullWidth
402→            size="large"
403→          >
404→            {buttonContent}
405→          </Button>
406→
407→          <Divider />
408→
409→          {/* Features */}
410→          <BlockStack gap="200">
411→            {plan.features.map((f) => (
412→              <PlanFeature key={f} feature={f} />
413→            ))}
414→          </BlockStack>
415→
416→        </BlockStack>
417→      </Box>
418→    </Box>
419→  );
420→}
