// ─── Plan card ────────────────────────────────────────────────────────────────

type PlanCardProps = {
  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planName: string) => void;
  loadingPlan: string | null;
};

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  loadingPlan,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isBestValue = "bestValue" in plan && plan.bestValue;
  const isCurrentPaid = currentTier !== "free";

  const isUpgrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);

  const isDowngrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);

  const shopifyPlan = isAnnual
    ? plan.shopifyPlanAnnual
    : plan.shopifyPlanMonthly;

  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;

  let buttonContent = "Start free trial";
  let buttonVariant: "primary" | "secondary" | "tertiary" = "primary";
  let buttonTone: "critical" | undefined;

  if (isCurrent) {
    buttonContent = "Current plan";
    buttonVariant = "tertiary";
  } else if (isUpgrade) {
    buttonContent = `Upgrade to ${plan.name}`;
    buttonVariant = "primary";
  } else if (isDowngrade && isCurrentPaid) {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = "secondary";
  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = "secondary";
  }

  const handleClick = () => {
    if (isCurrent) return;
    if (shopifyPlan) {
      onSubscribe(shopifyPlan);
    }
  };

  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");

  // Determine ribbon
  const showRibbon = isBestValue || isCurrent;
  const ribbonBg = isCurrent ? "bg-fill-success" : "bg-fill-info";
  const ribbonText = isCurrent ? "Your Plan" : "Most Popular";

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor={isCurrent ? "border-success" : isBestValue ? "border-info" : "border"}
      borderRadius="300"
      padding="0"
      overflowX="hidden"
      overflowY="hidden"
    >
      {/* Ribbon — only for current plan or best value */}
      {showRibbon && (
        <Box background={ribbonBg} paddingBlock="100" paddingInline="400">
          <Text as="p" variant="bodySm" fontWeight="semibold" alignment="center" tone="text-inverse">
            {ribbonText}
          </Text>
        </Box>
      )}

      <Box padding="500" paddingBlockStart={showRibbon ? "400" : "500"}>
        <BlockStack gap="500">

          {/* Header: name + description */}
          <BlockStack gap="100">
            <Text as="h3" variant="headingLg" fontWeight="bold">
              {plan.name}
            </Text>
            <Text as="p" variant="bodySm" tone="subdued">
              {plan.description}
            </Text>
          </BlockStack>

          {/* Price block */}
          <BlockStack gap="050">
            <InlineStack gap="050" blockAlign="baseline" wrap={false}>
              <Text as="p" variant="heading2xl" fontWeight="bold">
                ${displayPrice}
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                /mo
              </Text>
            </InlineStack>
            <Text as="p" variant="bodySm" tone="subdued">
              {isAnnual
                ? `$${plan.annualPrice} billed annually`
                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
            </Text>
          </BlockStack>

          {/* CTA */}
          <Button
            variant={buttonVariant}
            tone={buttonTone}
            onClick={handleClick}
            disabled={isCurrent}
            loading={isThisLoading}
            fullWidth
            size="large"
          >
            {buttonContent}
          </Button>

          <Divider />

          {/* Features */}
          <BlockStack gap="200">
            {plan.features.map((f) => (
              <PlanFeature key={f} feature={f} />
            ))}
          </BlockStack>

        </BlockStack>
      </Box>
    </Box>
  );
}

