  { label: "Cart & checkout blocking", free: false, starter: false, pro: true, ultimate: true },
  { label: "Custom widget CSS", free: false, starter: false, pro: false, ultimate: true },
  { label: "API access", free: false, starter: false, pro: false, ultimate: true },
  { label: "Priority support", free: false, starter: false, pro: true, ultimate: "24/7 VIP" },
];

const PLAN_ORDER = ["free", "starter", "pro", "ultimate"] as const;

const TIER_ORDER: Record<string, number> = {
  free: 0,
  starter: 1,
  pro: 2,
  ultimate: 3,
};

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const subscription = await getShopSubscription(shop);
  const isDev = process.env.NODE_ENV !== "production";
  return { subscription, isDev };
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs): Promise<
  | { error: string }
  | { success: boolean; message: string }
  | null
> => {
  const { session, billing } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = String(formData.get("intent"));

  if (intent === "subscribe") {
    const plan = String(formData.get("plan"));
    const returnUrl = `${process.env.SHOPIFY_APP_URL}/app/pricing`;
    try {
      /* eslint-disable @typescript-eslint/no-explicit-any */
      await billing.request({
        plan: plan as any,
        isTest: process.env.NODE_ENV !== "production",
        returnUrl,
      });
      /* eslint-enable @typescript-eslint/no-explicit-any */
      return null;
    } catch (error) {
      if (error instanceof Response) throw error;
      const errorData = (error as { errorData?: Array<{ field?: string; message?: string }> }).errorData;
      const details = errorData?.map((e) => e.message).join(", ");
      const message = details || (error instanceof Error ? error.message : String(error));

      if (message.includes("Custom apps cannot use the Billing API")) {
        return {
          error: "Billing is not available for custom apps. Please change your app distribution to 'Public' in the Shopify Partner Dashboard.",
        };
      }
      return {
        error: `Failed to initiate subscription: ${message}`,
      };
    }
  }

  if (intent === "test-set-plan") {
    const tier = String(formData.get("tier")) as import("../plans").PlanTier;
    const validTiers = ["free", "starter", "pro", "ultimate"];
    if (!validTiers.includes(tier)) {
      return { error: `Invalid plan tier: ${tier}` };
    }
    const planId = tier === "free" ? "free" : `${tier.charAt(0).toUpperCase() + tier.slice(1)} Monthly`;
    await db.subscription.upsert({
      where: { shop },
      create: { shop, planId, billingInterval: "monthly", status: "active" },
      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
    });
    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
  }

  if (intent === "cancel") {
    try {
      const sub = await getShopSubscription(shop);
      if (sub.shopifySubscriptionId) {
        await billing.cancel({
          subscriptionId: sub.shopifySubscriptionId,
          isTest: process.env.NODE_ENV !== "production",
          prorate: true,
        });
      }
      await cancelShopSubscription(shop);
      return {
        success: true,
        message: "Subscription cancelled. You are now on the Free plan.",
      };
    } catch {
      return { error: "Failed to cancel subscription. Please try again." };
    }
  }

  return null;
};

// ─── Sub-components ──────────────────────────────────────────────────────────

function PlanFeature({ feature }: { feature: string }) {
  return (
    <InlineStack gap="150" blockAlign="start" wrap={false}>
      <Box>
        <Icon source={CheckCircleIcon} tone="success" />
      </Box>
      <Text as="span" variant="bodyMd">
        {feature}
      </Text>
    </InlineStack>
  );
}

function ComparisonCell({ value, isCurrentPlan }: { value: FeatureValue; isCurrentPlan: boolean }) {
  return (
    <InlineStack align="center" blockAlign="center">
      {typeof value === "string" ? (
        <Text
          as="p"
          variant="bodyMd"
          fontWeight={isCurrentPlan ? "semibold" : "regular"}
          alignment="center"
        >
          {value}
        </Text>
      ) : (
        <Icon
          source={value ? CheckCircleIcon : XCircleIcon}
          tone={value ? "success" : "subdued"}
        />
      )}
    </InlineStack>
  );
}

// ─── Plan card ────────────────────────────────────────────────────────────────

type PlanCardProps = {
  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
  isAnnual: boolean;
  currentTier: string;
  onSubscribe: (planName: string) => void;
  loadingPlan: string | null;
};

function PlanCard({
  plan,
  isAnnual,
  currentTier,
  onSubscribe,
  loadingPlan,
}: PlanCardProps) {
  const isCurrent = currentTier === plan.id;
  const isBestValue = "bestValue" in plan && plan.bestValue;
  const isCurrentPaid = currentTier !== "free";

  const isUpgrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);

  const isDowngrade =
    !isCurrent &&
    plan.id !== "free" &&
    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);

  const shopifyPlan = isAnnual
    ? plan.shopifyPlanAnnual
    : plan.shopifyPlanMonthly;

  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;

  let buttonContent = "Start free trial";
  let buttonVariant: "primary" | "secondary" = "primary";

  if (isUpgrade) {
    buttonContent = `Upgrade to ${plan.name}`;
    buttonVariant = "primary";
  } else if (isDowngrade) {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = "secondary";
  } else if (!isCurrent && isCurrentPaid) {
    buttonContent = `Switch to ${plan.name}`;
    buttonVariant = "secondary";
  }

  const handleClick = () => {
    if (shopifyPlan) {
      onSubscribe(shopifyPlan);
    }
  };

  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");

  // Ribbon config — every card gets a ribbon area for consistent alignment
  const hasColoredRibbon = isBestValue || isCurrent;
  const ribbonBg = isCurrent
    ? "bg-fill-success"
    : isBestValue
      ? "bg-fill-info"
      : "bg-surface";
  const ribbonText = isCurrent
    ? "Your Plan"
    : isBestValue
      ? "Most Popular"
      : "";

  return (
    <Box
      background="bg-surface"
      borderWidth="025"
      borderColor={isCurrent ? "border-success" : isBestValue ? "border-info" : "border"}
      borderRadius="300"
      padding="0"
      overflowX="hidden"
      overflowY="hidden"
    >
      {/* Ribbon area — always rendered for height alignment across cards */}
      <Box
        background={ribbonBg}
        paddingBlock="100"
        paddingInline="400"
      >
        <Text
          as="p"
          variant="bodySm"
          fontWeight="semibold"
          alignment="center"
          tone={hasColoredRibbon ? "text-inverse" : undefined}
        >
          {ribbonText || "\u00A0"}
        </Text>
      </Box>

      <Box padding="500" paddingBlockStart="400">
        <BlockStack gap="400">

          {/* Header: name + description */}
          <BlockStack gap="100">
            <Text as="h3" variant="headingLg" fontWeight="bold">
              {plan.name}
            </Text>
            <Text as="p" variant="bodySm" tone="subdued">
              {plan.description}
            </Text>
          </BlockStack>

          {/* Price block */}
          <BlockStack gap="050">
            <InlineStack gap="050" blockAlign="baseline" wrap={false}>
              <Text as="p" variant="heading2xl" fontWeight="bold">
                ${displayPrice}
              </Text>
              <Text as="p" variant="bodySm" tone="subdued">
                /mo
              </Text>
            </InlineStack>
            <Text as="p" variant="bodySm" tone="subdued">
              {isAnnual
                ? `$${plan.annualPrice} billed annually`
                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
            </Text>
          </BlockStack>

          {/* CTA */}
          {isCurrent ? (
            <Box
              background="bg-surface-success"
              borderRadius="200"
              paddingBlock="200"
              paddingInline="400"
            >
              <Text as="p" variant="bodyMd" fontWeight="semibold" alignment="center" tone="success">
                Current plan
              </Text>
            </Box>
          ) : (
            <Button
              variant={buttonVariant}

              onClick={handleClick}
              loading={isThisLoading}
              fullWidth
              size="large"
            >
              {buttonContent}
            </Button>
          )}

          <Divider />

          {/* Features */}
          <BlockStack gap="200">
            {plan.features.map((f) => (
              <PlanFeature key={f} feature={f} />
            ))}
          </BlockStack>

        </BlockStack>
      </Box>
    </Box>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function PricingPage() {
  const { subscription, isDev } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const navigate = useNavigate();
  const shopify = useAppBridge();

  const [isAnnual, setIsAnnual] = useState(
    subscription.billingInterval === "annual",
  );
  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
  const [cancelModalOpen, setCancelModalOpen] = useState(false);

  const data = fetcher.data;
  const isFetching = fetcher.state !== "idle";

  useEffect(() => {
    if (!isFetching) setLoadingPlan(null);
    if (data && "message" in data && data.message) {
      shopify.toast.show(data.message as string);
    }
  }, [data, isFetching, shopify]);

  const actionError =
    data && "error" in data && data.error ? (data.error as string) : null;

  const handleSubscribe = useCallback(
    (planName: string) => {
      setLoadingPlan(planName);
      const fd = new FormData();
      fd.set("intent", "subscribe");
      fd.set("plan", planName);
      fetcher.submit(fd, { method: "POST" });
    },
    [fetcher],
  );

  const handleConfirmCancel = useCallback(() => {
    setCancelModalOpen(false);
    setLoadingPlan("cancel");
    const fd = new FormData();
    fd.set("intent", "cancel");
    fetcher.submit(fd, { method: "POST" });
  }, [fetcher]);

  const currentTier = subscription.planTier;
  const isFreeTier = currentTier === "free";

  return (
    <Page
      title="Pricing"
      subtitle="Choose the plan that's right for your store"
      backAction={{ onAction: () => navigate("/app") }}
    >
      <Box paddingBlockEnd="1600">
        <BlockStack gap="600">

          {/* Error banner */}
          {actionError && (
            <Banner tone="critical" title="Billing error">
              <Text as="p" variant="bodyMd">{actionError}</Text>
            </Banner>
          )}

          {/* ── Section 1: Billing toggle ── */}
          <InlineStack align="center">
            <ButtonGroup variant="segmented">
              <Button
                pressed={!isAnnual}
                onClick={() => setIsAnnual(false)}
              >
                Monthly
              </Button>
              <Button
                pressed={isAnnual}
                onClick={() => setIsAnnual(true)}
              >
                Annual · Save up to 38%
              </Button>
            </ButtonGroup>
          </InlineStack>

          {/* ── Section 2: Free plan — full-width card ── */}
          <Box
            background="bg-surface"
            borderWidth="025"
            borderColor={isFreeTier ? "border-success" : "border"}
            borderRadius="300"
            padding="0"
            overflowX="hidden"
            overflowY="hidden"
          >
            {/* Ribbon — consistent with paid cards */}
            <Box
              background={isFreeTier ? "bg-fill-success" : "bg-surface"}
              paddingBlock="100"
              paddingInline="400"
            >
              <Text
                as="p"
                variant="bodySm"
                fontWeight="semibold"
                alignment="center"
                tone={isFreeTier ? "text-inverse" : undefined}
              >
                {isFreeTier ? "Your Plan" : "\u00A0"}
              </Text>
            </Box>

            <Box padding="500" paddingBlockStart="400">
              <BlockStack gap="400">
                {/* Top row: plan info + price + button */}
                <InlineGrid columns={{ xs: 1, md: "1fr auto auto" }} gap="500" alignItems="center">
                  <BlockStack gap="050">
                    <Text as="h3" variant="headingLg" fontWeight="bold">
                      Free
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      {PLANS_DATA.free.description}
                    </Text>
                  </BlockStack>

                  <InlineStack gap="050" blockAlign="baseline" wrap={false}>
                    <Text as="p" variant="heading2xl" fontWeight="bold">
                      $0
                    </Text>
                    <Text as="p" variant="bodySm" tone="subdued">
                      forever
                    </Text>
                  </InlineStack>

                  <Box minWidth="200px">
                    {isFreeTier ? (
                      <Box
                        background="bg-surface-success"
                        borderRadius="200"
                        paddingBlock="200"
                        paddingInline="400"
                      >
                        <Text as="p" variant="bodyMd" fontWeight="semibold" alignment="center" tone="success">
                          Current plan
                        </Text>
                      </Box>
                    ) : (
                      <Button
                        variant="secondary"
                        tone="critical"
                        onClick={() => setCancelModalOpen(true)}
                        loading={loadingPlan === "cancel"}
                        fullWidth
                        size="large"
                      >
                        Downgrade to Free
                      </Button>
                    )}
                  </Box>
                </InlineGrid>

                <Divider />

                {/* Features row */}
                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="200">
                  {PLANS_DATA.free.features.map((f) => (
                    <PlanFeature key={f} feature={f} />
                  ))}
                </InlineGrid>
              </BlockStack>
            </Box>
          </Box>

          {/* ── Section 3: Paid plan cards — 3 columns ── */}
          <InlineGrid columns={{ xs: 1, md: 3 }} gap="400">
            <PlanCard
              plan={PLANS_DATA.starter}
              isAnnual={isAnnual}
              currentTier={currentTier}
              onSubscribe={handleSubscribe}
              loadingPlan={loadingPlan}
            />
            <PlanCard
              plan={PLANS_DATA.pro}
              isAnnual={isAnnual}
              currentTier={currentTier}
              onSubscribe={handleSubscribe}
              loadingPlan={loadingPlan}
            />
            <PlanCard
              plan={PLANS_DATA.ultimate}
              isAnnual={isAnnual}
              currentTier={currentTier}
              onSubscribe={handleSubscribe}
              loadingPlan={loadingPlan}
            />
          </InlineGrid>

          {/* ── Section 4: Trial note ── */}
          <Text as="p" variant="bodySm" tone="subdued" alignment="center">
            All paid plans include a 7-day free trial. No credit card charged until the trial ends.
          </Text>

          {/* ── Section 5: Feature comparison table ── */}
          <BlockStack gap="300">
            <Text as="h2" variant="headingLg" alignment="center">
              Full Feature Comparison
            </Text>

            <Card padding="0">
              <BlockStack gap="0">
                {/* Table header */}
                <Box padding="400" paddingBlockEnd="300">
                  <InlineGrid columns="4fr 2fr 2fr 2fr 2fr" gap="300" alignItems="end">
                    <Box>
                      <Text as="p" variant="bodySm" fontWeight="semibold" tone="subdued">
                        Feature
                      </Text>
                    </Box>
                    {PLAN_ORDER.map((id) => {
                      const plan = PLANS_DATA[id];
                      const isCurrentCol = currentTier === id;
                      return (
                        <Box
                          key={id}
                          background={isCurrentCol ? "bg-surface-success" : undefined}
                          borderRadius="200"
                          padding="200"
                        >
                          <BlockStack gap="050" inlineAlign="center">
                            <Text
                              as="p"
                              variant="headingSm"
                              fontWeight="bold"
                              alignment="center"
                              tone={isCurrentCol ? "success" : undefined}
                            >
                              {plan.name}
                            </Text>
                            <Text as="p" variant="bodySm" tone="subdued" alignment="center">
                              {plan.monthlyPrice === 0
                                ? "Free"
                                : isAnnual
                                  ? `$${plan.annualMonthlyPrice}/mo`
                                  : `$${plan.monthlyPrice}/mo`}
                            </Text>
                          </BlockStack>
                        </Box>
                      );
                    })}
                  </InlineGrid>
                </Box>

                <Divider />

                {/* Table rows */}
                {FEATURE_ROWS.map((row, i) => (
                  <Box key={row.label}>
                    <Box
                      padding="400"
                      paddingBlock="300"
                      background={i % 2 === 0 ? "bg-surface" : "bg-surface-secondary"}
                    >
                      <InlineGrid columns="4fr 2fr 2fr 2fr 2fr" gap="300" alignItems="center">
                        <Text as="p" variant="bodyMd">
                          {row.label}
                        </Text>
                        {PLAN_ORDER.map((id) => (
                          <ComparisonCell
                            key={id}
                            value={row[id]}
                            isCurrentPlan={currentTier === id}
                          />
                        ))}
                      </InlineGrid>
                    </Box>
                  </Box>
                ))}
              </BlockStack>
            </Card>
          </BlockStack>

          {/* ── Dev-only: Set plan manually ── */}
          {isDev && (
            <Banner tone="info" title="Development Mode: Set Plan Manually">
              <BlockStack gap="300">
                <Text as="p" variant="bodySm">
                  This section is only visible in development. Select a plan to activate it directly in the database:
                </Text>
                <InlineStack gap="200">
                  {(["free", "starter", "pro", "ultimate"] as const).map((tier) => (
                    <Button
                      key={tier}
                      size="slim"
                      variant={currentTier === tier ? "primary" : "secondary"}
                      disabled={currentTier === tier}
                      onClick={() => {
                        const fd = new FormData();
                        fd.set("intent", "test-set-plan");
                        fd.set("tier", tier);
                        fetcher.submit(fd, { method: "POST" });
                      }}
                    >
                      {tier.charAt(0).toUpperCase() + tier.slice(1)}
                    </Button>
                  ))}
                </InlineStack>
              </BlockStack>
            </Banner>
          )}

        </BlockStack>
      </Box>

      {/* ── Downgrade confirmation modal ── */}
      <Modal
        open={cancelModalOpen}
        onClose={() => setCancelModalOpen(false)}
        title="Downgrade to Free plan?"
        primaryAction={{
          content: "Yes, downgrade",
          destructive: true,
          onAction: handleConfirmCancel,
          loading: loadingPlan === "cancel",
        }}
        secondaryActions={[
          {
            content: "Keep current plan",
            onAction: () => setCancelModalOpen(false),
          },
        ]}
      >
        <Modal.Section>
          <BlockStack gap="400">
            <Text as="p" variant="bodyMd">
              Downgrading to Free will immediately remove access to:
            </Text>
            <BlockStack gap="200">
              {[
                "Unlimited zip codes — limited to 20",
                "Blocked zip codes",
                "Delivery rules, zones & ETAs",
                "Bulk CSV import & export",
                "Customer waitlist",
                "Widget customization (colors, position)",
                "Cart & checkout blocking",
              ].map((item) => (
                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
                  <Box>
                    <Icon source={XCircleIcon} tone="critical" />
                  </Box>
                  <Text as="p" variant="bodyMd">{item}</Text>
                </InlineStack>
              ))}
            </BlockStack>
            <Banner tone="warning">
              <Text as="p" variant="bodyMd">
                Zip codes over the 20-entry limit will remain saved but become
                inactive until you upgrade again.
              </Text>
            </Banner>
          </BlockStack>
        </Modal.Section>
      </Modal>
    </Page>
  );
}

export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

