                onClick={() => setIsAnnual(true)}
              >
                Annual · Save up to 38%
              </Button>
            </ButtonGroup>
          </InlineStack>

          {/* Free plan — full-width card */}
          <Card padding="0">
            <Box padding="500">
              <BlockStack gap="400">
                {/* Top row: info + price + button */}
                <InlineGrid columns={{ xs: 1, md: "1fr auto auto" }} gap="400" alignItems="center">
                  <BlockStack gap="050">
