285→
286→function PlanCard({
287→  plan,
288→  isAnnual,
289→  currentTier,
290→  onSubscribe,
291→  loadingPlan,
292→}: PlanCardProps) {
293→  const isCurrent = currentTier === plan.id;
294→  const isBestValue = "bestValue" in plan && plan.bestValue;
295→  const isCurrentPaid = currentTier !== "free";
296→
297→  const isUpgrade =
298→    !isCurrent &&
299→    plan.id !== "free" &&
300→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
301→
302→  const isDowngrade =
303→    !isCurrent &&
304→    plan.id !== "free" &&
305→    (TIER_ORDER[plan.id] ?? 0) < (TIER_ORDER[currentTier] ?? 0);
306→
307→  const shopifyPlan = isAnnual
308→    ? plan.shopifyPlanAnnual
309→    : plan.shopifyPlanMonthly;
310→
311→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
312→
313→  let buttonContent = "Start free trial";
314→  let buttonVariant: "primary" | "secondary" = "primary";
315→
316→  if (isCurrent) {
317→    buttonContent = "Current plan";
318→    buttonVariant = "secondary";
319→  } else if (isUpgrade) {
320→    buttonContent = `Upgrade to ${plan.name}`;
321→    buttonVariant = "primary";
322→  } else if (isDowngrade) {
323→    buttonContent = `Switch to ${plan.name}`;
324→    buttonVariant = "secondary";
325→  } else if (!isCurrent && isCurrentPaid) {
326→    buttonContent = `Switch to ${plan.name}`;
327→    buttonVariant = "secondary";
328→  }
329→
330→  const handleClick = () => {
331→    if (shopifyPlan) {
332→      onSubscribe(shopifyPlan);
333→    }
334→  };
335→
336→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
337→
338→  return (
339→    <Box
340→      background="bg-surface"
341→      borderWidth="025"
342→      borderColor="border"
343→      borderRadius="300"
344→      padding="0"
345→      overflowX="hidden"
346→      overflowY="hidden"
347→    >
348→      {/* Top accent — thin bar for recommended plan, transparent spacer for others */}
349→      <Box
350→        background={isBestValue && !isCurrent ? "bg-fill-info" : undefined}
351→        minHeight="4px"
352→      />
353→
354→      <Box padding="500">
355→        <BlockStack gap="400">
356→
357→          {/* Plan name + badges */}
358→          <BlockStack gap="100">
359→            <InlineStack gap="200" blockAlign="center" wrap={false}>
360→              <Text as="h3" variant="headingLg" fontWeight="bold">
361→                {plan.name}
362→              </Text>
363→              {isCurrent && <Badge tone="success">Active</Badge>}
364→              {isBestValue && !isCurrent && <Badge tone="info-strong">Most popular</Badge>}
365→            </InlineStack>
366→            <Text as="p" variant="bodyMd" tone="subdued">
367→              {plan.description}
368→            </Text>
369→          </BlockStack>
370→
371→          {/* Price */}
372→          <BlockStack gap="050">
373→            <InlineStack gap="100" blockAlign="baseline" wrap={false}>
374→              <Text as="p" variant="heading2xl" fontWeight="bold">
375→                ${displayPrice}
376→              </Text>
377→              <Text as="p" variant="bodyMd" tone="subdued">
378→                /mo
379→              </Text>
380→            </InlineStack>
381→            <Text as="p" variant="bodyMd" tone="subdued">
382→              {isAnnual
383→                ? `$${plan.annualPrice} billed annually`
384→                : `or $${plan.annualMonthlyPrice}/mo billed annually`}
385→            </Text>
386→          </BlockStack>
387→
388→          {/* CTA */}
389→          <Button
390→            variant={buttonVariant}
391→            onClick={handleClick}
392→            disabled={isCurrent}
393→            loading={isThisLoading}
394→            fullWidth
395→            size="large"
396→          >
397→            {buttonContent}
398→          </Button>
399→
400→          <Divider />
401→
402→          {/* Features */}
403→          <BlockStack gap="300">
404→            {plan.features.map((f) => (
405→              <PlanFeature key={f} feature={f} />
406→            ))}
407→          </BlockStack>
408→
409→        </BlockStack>
410→      </Box>
411→    </Box>
412→  );
413→}
