  1→/**
  2→ * Centralized Resend email service.
  3→ *
  4→ * All send functions return `true` on success, `false` on failure — they never
  5→ * throw. This lets callers fire-and-forget without wrapping in try/catch.
  6→ */
  7→import { Resend } from "resend";
  8→
  9→// ---------------------------------------------------------------------------
 10→// Types
 11→// ---------------------------------------------------------------------------
 12→
 13→export interface EmailOptions {
 14→  /** Display name in the From field (e.g. "Cool Store"). Defaults to shopDisplayName. */
 15→  senderName?: string | null;
 16→  /** Cached Shopify store display name (from ShopSettings.shopName). Falls back to myshopify slug. */
 17→  shopDisplayName?: string | null;
 18→  /** Reply-to email for customer-facing emails. If empty, no reply-to header is added. */
 19→  replyTo?: string | null;
 20→}
 21→
 22→// ---------------------------------------------------------------------------
 23→// Client singleton
 24→// ---------------------------------------------------------------------------
 25→
 26→let client: Resend | null = null;
 27→
 28→function getClient(): Resend | null {
 29→  if (client) return client;
 30→  const apiKey = process.env.RESEND_API_KEY;
 31→  if (!apiKey) {
 32→    console.warn("[email] RESEND_API_KEY not set — emails will be skipped");
 33→    return null;
 34→  }
 35→  client = new Resend(apiKey);
 36→  return client;
 37→}
 38→
 39→function getRawFromEmail(): string {
 40→  return process.env.RESEND_FROM_EMAIL || "noreply@example.com";
 41→}
 42→
 43→function shopFallbackName(shop: string, options?: EmailOptions): string {
 44→  return options?.shopDisplayName?.trim() || shop.replace(".myshopify.com", "");
 45→}
 46→
 47→/**
 48→ * Build the full From address with display name.
 49→ *
 50→ * - Custom sender name set:  "Cool Store via Pinzo <noreply@boldteq.app>"
 51→ * - No custom name:          "cool-store via Pinzo <noreply@boldteq.app>"
 52→ */
 53→function buildFrom(shop: string, options?: EmailOptions): string {
 54→  const displayName = options?.senderName?.trim() || shopFallbackName(shop, options);
 55→  return `${displayName} via Pinzo <${getRawFromEmail()}>`;
 56→}
 57→
 58→/**
 59→ * Build optional reply_to field. Returns undefined when not configured
 60→ * so it can be spread into the Resend payload without adding an empty header.
 61→ */
 62→function buildReplyTo(options?: EmailOptions): { reply_to: string } | Record<string, never> {
 63→  const replyTo = options?.replyTo?.trim();
 64→  if (replyTo) return { reply_to: replyTo };
 65→  return {};
 66→}
 67→
 68→// ---------------------------------------------------------------------------
 69→// 1. Waitlist Confirmation  (App → Customer)
 70→// ---------------------------------------------------------------------------
 71→
 72→export async function sendWaitlistConfirmation(
 73→  to: string,
 74→  zipCode: string,
 75→  shop: string,
 76→  options?: EmailOptions,
 77→): Promise<boolean> {
 78→  const resend = getClient();
 79→  if (!resend) return false;
 80→
 81→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
 82→
 83→  try {
 84→    await resend.emails.send({
 85→      from: buildFrom(shop, options),
 86→      to,
 87→      subject: `You're on the waitlist — ${name}`,
 88→      html: `
 89→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
 90→          <h2 style="margin:0 0 16px">You're on the waitlist!</h2>
 91→          <p>Thanks for signing up. We'll let you know as soon as delivery is available to <strong>${zipCode}</strong>.</p>
 92→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
 93→        </div>
 94→      `,
 95→      text: `You're on the waitlist!\n\nThanks for signing up. We'll let you know as soon as delivery is available to ${zipCode}.\n\n— ${name}`,
 96→      ...buildReplyTo(options),
 97→    });
 98→    return true;
 99→  } catch (error) {
100→    console.error("[email] Failed to send waitlist confirmation:", error);
101→    return false;
102→  }
103→}
104→
105→// ---------------------------------------------------------------------------
106→// 2. Merchant Alert  (App → Merchant)
107→// ---------------------------------------------------------------------------
108→
109→export async function sendMerchantWaitlistAlert(
110→  to: string,
111→  customerEmail: string,
112→  zipCode: string,
113→  shop: string,
114→  options?: EmailOptions,
115→): Promise<boolean> {
116→  const resend = getClient();
117→  if (!resend) return false;
118→
119→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
120→
121→  try {
122→    await resend.emails.send({
123→      from: buildFrom(shop, options),
124→      to,
125→      subject: `New waitlist signup: ${zipCode}`,
126→      html: `
127→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
128→          <h2 style="margin:0 0 16px">New waitlist signup</h2>
129→          <p>A customer just joined the waitlist for ZIP code <strong>${zipCode}</strong>.</p>
130→          <table style="margin:16px 0;border-collapse:collapse">
131→            <tr><td style="padding:4px 12px 4px 0;color:#666">Email</td><td>${customerEmail}</td></tr>
132→            <tr><td style="padding:4px 12px 4px 0;color:#666">ZIP Code</td><td>${zipCode}</td></tr>
133→          </table>
134→          <p style="color:#666;font-size:13px">You can manage the waitlist from your <strong>${name}</strong> admin dashboard.</p>
135→        </div>
136→      `,
137→      text: `New waitlist signup\n\nA customer (${customerEmail}) just joined the waitlist for ZIP code ${zipCode}.\n\nManage the waitlist from your ${name} admin dashboard.`,
138→      ...buildReplyTo(options),
139→    });
140→    return true;
141→  } catch (error) {
142→    console.error("[email] Failed to send merchant waitlist alert:", error);
143→    return false;
144→  }
145→}
146→
147→// ---------------------------------------------------------------------------
148→// 3. ZIP Available Notification  (App → Customer)
149→// ---------------------------------------------------------------------------
150→
151→export async function sendZipAvailableNotification(
152→  to: string,
153→  zipCode: string,
154→  shop: string,
155→  shopUrl: string,
156→  options?: EmailOptions,
157→): Promise<boolean> {
158→  const resend = getClient();
159→  if (!resend) return false;
160→
161→  const name = options?.senderName?.trim() || shopFallbackName(shop, options);
162→
163→  try {
164→    await resend.emails.send({
165→      from: buildFrom(shop, options),
166→      to,
167→      subject: `Great news! We now deliver to ${zipCode}`,
168→      html: `
169→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
170→          <h2 style="margin:0 0 16px">Great news!</h2>
171→          <p>We're excited to let you know that delivery is now available to ZIP code <strong>${zipCode}</strong>.</p>
172→          <p><a href="${shopUrl}" style="display:inline-block;padding:10px 20px;background:#008060;color:#fff;text-decoration:none;border-radius:4px;margin-top:8px">Shop Now</a></p>
173→          <p style="color:#666;font-size:13px;margin-top:24px">— ${name}</p>
174→        </div>
175→      `,
176→      text: `Great news!\n\nDelivery is now available to ZIP code ${zipCode}. Visit ${shopUrl} to place your order.\n\n— ${name}`,
177→      ...buildReplyTo(options),
178→    });
179→    return true;
180→  } catch (error) {
181→    console.error("[email] Failed to send ZIP available notification:", error);
182→    return false;
183→  }
184→}
185→
186→// ---------------------------------------------------------------------------
187→// 4. Test Email  (Settings page)
188→// ---------------------------------------------------------------------------
189→
190→export async function sendTestEmail(
191→  to: string,
192→  options?: EmailOptions,
193→  shop?: string,
194→): Promise<boolean> {
195→  const resend = getClient();
196→  if (!resend) return false;
197→
198→  const name = options?.senderName?.trim() || (shop ? shopFallbackName(shop, options) : "Your Store");
199→
200→  try {
201→    await resend.emails.send({
202→      from: buildFrom(shop || "test-store.myshopify.com", options),
203→      to,
204→      subject: "Pinzo — Test Email",
205→      html: `
206→        <div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px">
207→          <h2 style="margin:0 0 16px">Test email received!</h2>
208→          <p>Your email integration is working correctly.</p>
209→          <p style="margin-top:16px"><strong>From:</strong> ${name} via Pinzo &lt;${getRawFromEmail()}&gt;</p>
210→          ${options?.replyTo ? `<p><strong>Reply-To:</strong> ${options.replyTo}</p>` : "<p><strong>Reply-To:</strong> <em>Not set</em></p>"}
211→          <p style="color:#666;font-size:13px;margin-top:24px">You will receive notifications when customers join your waitlist.</p>
212→        </div>
213→      `,
214→      text: `Test email received!\n\nYour email integration is working correctly.\n\nFrom: ${name} via Pinzo <${getRawFromEmail()}>\nReply-To: ${options?.replyTo || "Not set"}\n\nYou will receive notifications when customers join your waitlist.`,
215→      ...buildReplyTo(options),
216→    });
217→    return true;
218→  } catch (error) {
219→    console.error("[email] Failed to send test email:", error);
220→    return false;
221→  }
222→}
